import { Engine, EngineConfiguration, UIScene, UIScale, UILabel, WorldNode, Pivot, Vector2 } from "./build/vanilla.js";

class MainScene extends UIScene {
	constructor() {
		super();
		this.setLoadingMinDurationMs(0);
	}

	initialize(engine) {
		super.initialize(engine);
		const layerNode = new WorldNode();
		layerNode.setPivot(Pivot.topLeft);
		layerNode.setAnchor(Pivot.topLeft);
		const labelNode = new WorldNode();
		labelNode.setPivot(Pivot.topLeft);
		labelNode.setAnchor(Pivot.topLeft);
		labelNode.setLocalPosition(Vector2.create(16, 16));
		labelNode.setContentSize(Vector2.create(240, 32));
		const label = labelNode.addComponent(UILabel);
		label.setText("Readable on small screens");
		label.setFontSize(16);
		layerNode.addChild(labelNode);
		const root = this.getRoot();
		root.addChild(layerNode);

		const viewManager = engine.getViewManager();
		const viewSize = viewManager.getViewSize();
		const uiScale = UIScale.read(viewSize.x, viewSize.y, { minimumLayerHeight: 320 });
		layerNode.setLocalScale(Vector2.create(uiScale, uiScale));
		console.log("ui scale", uiScale);
	}
}

const engineConfiguration = new EngineConfiguration();
engineConfiguration.canvasId = "mainCanvas";
engineConfiguration.referenceResolutionSize = Vector2.create(640, 360);
engineConfiguration.autoResizeOnWindowResize = true;
const engine = new Engine(engineConfiguration);
engine.run(new MainScene());

import { Engine, EngineConfiguration, UIScene, UIWindow, UIWindowLayer, UILabel, WorldNode, Pivot, Vector2 } from "./build/vanilla.js";

class NoticeWindow extends UIWindow {
	#messageNode;

	constructor(name, messageText) {
		super(name);
		const messageNode = new WorldNode();
		messageNode.setPivot(Pivot.topLeft.clone());
		messageNode.setAnchor(Pivot.topLeft.clone());
		const messageLabel = messageNode.addComponent(UILabel);
		messageLabel.setText(messageText);
		messageLabel.setFontSize(18);
		const panelNode = this.getPanelNode();
		panelNode.addChild(messageNode);
		this.#messageNode = messageNode;
	}

	getMessageNode() {
		return this.#messageNode;
	}

	layoutContent(panelWidth) {
		const messageNode = this.getMessageNode();
		messageNode.setLocalPosition(Vector2.create(24, 24));
		messageNode.setContentSize(Vector2.create(panelWidth - 48, 64));
		return 112;
	}
}

class WindowScene extends UIScene {
	initialize(engine) {
		super.initialize(engine);
		const root = this.getRoot();
		const rootSize = root.getContentSize();
		const windowLayer = new UIWindowLayer();
		root.addChild(windowLayer);
		windowLayer.setViewSize(rootSize.x, rootSize.y);
		const noticeWindow = new NoticeWindow("notice", "New items arrived in the shop.");
		noticeWindow.setMaximumWidth(360);
		noticeWindow.setOutsideCloseEnabled(false);
		windowLayer.openWindow(noticeWindow);
	}
}

const engineConfiguration = new EngineConfiguration();
const engine = new Engine(engineConfiguration);
const scene = new WindowScene();
scene.setLoadingMinDurationMs(0);
engine.run(scene);

summary.ko:
창 층. (영역 위에 UIWindow 를 쌓는다)
- 창을 띄우면 맨 위에 쌓고, 맨 위의 창만 보인다. 위의 창이 닫히면 아래 창이 다시 보인다.
- 닫으면 목록에서 바로 빠져 누름과 덮임이 바로 풀리고, 닫는 움직임(PopupMotion)이 끝난 뒤에 떼어 낸다.
  덮여 있던 창을 닫으면 움직임 없이 바로 떼어 낸다.
- 이 층은 UI 배율(UIScale.read)만큼 커지고, 창에는 그만큼 나눈 영역의 크기와 세이프에어리어 너비를 알린다. (작은 화면에서도 글자가 읽히게)
  setUIScaleOptions(null) 이면 키우지 않는다.
- 창이 하나라도 떠 있는 동안은 놀이 밖이다. 창이 뜨고 닫힐 때 알리므로(setWindowChangeEvent) 게임이 놀이를 멈추고 이어 간다.
- 휠은 맨 위의 창이 먼저 받는다(UIWindow.handleWheel), 받지 않으면 그 자리의 스크롤 뷰. GameScene 은 창 층 안을 가리킨 휠을 scrollWindowAt 으로 넘긴다.
- 사용: (영역 노드의 맨 위 자식으로 두고, 영역 크기가 바뀔 때마다 알린다)
    const windowLayer = new UIWindowLayer();
    playAreaNode.addChild(windowLayer);
    windowLayer.setViewSize(playAreaWidth, playAreaHeight);
    windowLayer.setViewBleed(insets.top, insets.right, insets.bottom, insets.left);
    windowLayer.setWindowChangeEvent(() => { game.setPaused(windowLayer.hasOpenWindow()); });
    windowLayer.openWindow(new UIConfirmWindow("quit", { title: "나가기", message: "정말 나갈까요?" }));

summary.en:
Window layer. (stacks UIWindow over the area)
- Opening a window stacks it on top, and only the top window is visible. When the upper window closes, the window below is visible again.
- Closing removes it from the list immediately so presses and covering are released at once, and it is detached after the close motion (PopupMotion) finishes.
  Closing a window that was covered detaches it immediately without motion.
- This layer is enlarged by the UI scale (UIScale.read), and windows are notified of the area size and safe area width divided by that amount. (so text is readable even on small screens)
  With setUIScaleOptions(null) it does not enlarge.
- While even one window is open, play is suspended. It notifies when windows open and close (setWindowChangeEvent), so the game pauses and resumes play.
- The top window receives the wheel first (UIWindow.handleWheel), and if it does not handle it, the scroll view at that position. GameScene passes wheel input pointing inside the window layer to scrollWindowAt.
- Usage: (place it as the topmost child of the area node, and notify it whenever the area size changes)
    const windowLayer = new UIWindowLayer();
    playAreaNode.addChild(windowLayer);
    windowLayer.setViewSize(playAreaWidth, playAreaHeight);
    windowLayer.setViewBleed(insets.top, insets.right, insets.bottom, insets.left);
    windowLayer.setWindowChangeEvent(() => { game.setPaused(windowLayer.hasOpenWindow()); });
    windowLayer.openWindow(new UIConfirmWindow("quit", { title: "Quit", message: "Do you really want to quit?" }));

