import { Engine, EngineConfiguration, UIScene, UIWindow, UIWindowLayer } from "./build/vanilla.js";

class WindowLayerScene extends UIScene {
	initialize(engine) {
		super.initialize(engine);
		const root = this.getRoot();
		const rootSize = root.getContentSize();
		const windowLayer = new UIWindowLayer();
		root.addChild(windowLayer);
		windowLayer.setViewSize(rootSize.x, rootSize.y);
		windowLayer.setWindowChangeEvent(() => {
			const windowCount = windowLayer.getWindowCount();
			console.log(windowCount);
		});

		const settingsWindow = new UIWindow("settings");
		settingsWindow.setPanelHeight(220);
		windowLayer.openWindow(settingsWindow);
		const helpWindow = new UIWindow("help");
		helpWindow.setPanelHeight(140);
		helpWindow.setMaximumWidth(300);
		windowLayer.openWindow(helpWindow);

		const isClosed = windowLayer.closeTopWindow();
		const topWindow = windowLayer.getTopWindow();
		const topWindowName = topWindow.getName();
		console.log(isClosed, topWindowName);
	}
}

const engineConfiguration = new EngineConfiguration();
const engine = new Engine(engineConfiguration);
const scene = new WindowLayerScene();
scene.setLoadingMinDurationMs(0);
engine.run(scene);

summary.ko:
확인 창. (제목, 묻는 글, 취소와 확인 두 단추)
- UIWindow 라 UIWindowLayer 로 띄운다. 묻는 글은 판의 너비에서 줄을 바꾸고 줄 수에 맞춰 판의 세로가 정해진다.
  글이 길어 영역의 세로를 넘으면 글 칸만 스크롤되고 두 단추는 늘 보인다.
- 단추는 왼쪽이 취소, 오른쪽이 확인(강조)이다. 오른쪽에서 왼쪽 언어(setRightToLeft)면 차례를 뒤집는다.
- 확인을 누르면 확인 알림 뒤 닫힌다. 취소, 바깥 누르기, closeTopWindow, closeAllWindows 로 닫히면 취소 알림이다.
- 판 모양은 UIWindow 와 같다. 단추와 글의 색은 getConfirmButtonNode() 들로 꺼내 바꾼다.
- 사용:
    const confirmWindow = new UIConfirmWindow("quit", { title: "나가기", message: "정말 나갈까요?", cancelText: "취소", confirmText: "나가기" });
    confirmWindow.setConfirmEvent(() => { leave(); });
    windowLayer.openWindow(confirmWindow);

summary.en:
Confirm window. (title, question text, two buttons: cancel and confirm)
- Being a UIWindow, it is opened with UIWindowLayer. The question text wraps at the panel width and the panel height is set by the number of lines.
  If the text is long and exceeds the area height, only the text box scrolls and the two buttons are always visible.
- The buttons are cancel on the left and confirm (emphasized) on the right. For right-to-left languages (setRightToLeft) the order is reversed.
- Pressing confirm closes it after the confirm notification. Closing via cancel, pressing outside, closeTopWindow or closeAllWindows gives the cancel notification.
- The panel look is the same as UIWindow. Button and text colors are changed by getting the nodes with getConfirmButtonNode() and the like.
- Usage:
    const confirmWindow = new UIConfirmWindow("quit", { title: "Quit", message: "Do you really want to quit?", cancelText: "Cancel", confirmText: "Quit" });
    confirmWindow.setConfirmEvent(() => { leave(); });
    windowLayer.openWindow(confirmWindow);

